/**
 * Blog content blocks. Plain strings render as paragraphs; typed objects
 * render as specialised components (H2/H3, callouts, quotes, stats, tables).
 * The renderer lives in app/blog/[slug]/page.tsx.
 */
export type BlogBlock =
  | string
  | { h2: string }
  | { h3: string }
  | { callout: { variant?: "info" | "tip" | "warning" | "danger" | "success"; title?: string; body: string } }
  | { quote: { text: string; author: string; role?: string; url?: string; accent?: boolean } }
  | {
      stats: {
        items: { value: string; label: string; sub?: string; accent?: boolean }[];
        source?: string;
        sourceUrl?: string;
      };
    }
  | {
      comparison: {
        columns: { title: string; subtitle?: string; badge?: string; accent?: boolean }[];
        rows: { criterion: string; values: (string | boolean)[]; highlight?: boolean }[];
        caption?: string;
        footnote?: string;
      };
    }
  | { code: { lang?: string; content: string } }
  | { img: { src: string; alt: string; caption?: string } };

