export function getFaq(slug: string): { q: string; a: string }[] | undefined {
  // Check inline faq on post first, then legacy FAQ_BY_SLUG map
  const post = POSTS.find((p) => p.slug === slug);
  const raw = post?.faq ?? FAQ_BY_SLUG[slug];
  return raw ? renderPriceDeep(raw) : undefined;
}

