export function getHowTo(slug: string): HowToMeta | undefined {
  const raw = HOWTO_BY_SLUG[slug];
  return raw ? renderPriceDeep(raw) : undefined;
}

export function getRelated(slug: string): BlogPost[] {
  const slugs = RELATED_BY_SLUG[slug];
  if (slugs) {
    return slugs.map((s) => POSTS.find((p) => p.slug === s)).filter((p): p is BlogPost => !!p);
  }
  const current = POSTS.find((p) => p.slug === slug);
  if (current) {
    const myTags = new Set((current.tags ?? []).map((t) => t.toLowerCase()));
    const scored = POSTS.filter((p) => p.slug !== slug).map((p) => {
      const theirTags = new Set((p.tags ?? []).map((t) => t.toLowerCase()));
      let overlap = 0;
      myTags.forEach((t) => { if (theirTags.has(t)) overlap += 1; });
      const union = new Set<string>(Array.from(myTags).concat(Array.from(theirTags))).size || 1;
      const sameCategory = p.category && p.category === current.category ? 0.15 : 0;
      return { post: p, score: overlap / union + sameCategory };
    });
    const ranked = scored
      .filter((x) => x.score > 0)
      .sort((a, b) => b.score - a.score || b.post.date.localeCompare(a.post.date));
    if (ranked.length >= 2) return ranked.slice(0, 4).map((x) => x.post);
    const seen = new Set(ranked.map((x) => x.post.slug));
    const fillers = SORTED_POSTS.filter((p) => p.slug !== slug && !seen.has(p.slug));
    return [...ranked.map((x) => x.post), ...fillers].slice(0, 4);
  }
  // Fallback: 4 most recent other posts
  return SORTED_POSTS.filter((p) => p.slug !== slug).slice(0, 4);
}

export function getPost(slug: string): BlogPost | undefined {
  return POSTS.find((p) => p.slug === slug);
}

export function getPostsByCategory(category: BlogCategorySlug): BlogPost[] {
  return SORTED_POSTS.filter((p) => p.category === category);
}

export function getCategory(slug: string): BlogCategory | undefined {
  return BLOG_CATEGORY_BY_SLUG[slug];
}

const CYR_TO_LAT: Record<string, string> = {
  а: "a", б: "b", в: "v", г: "g", д: "d", е: "e", ё: "e", ж: "zh", з: "z",
  и: "i", й: "i", к: "k", л: "l", м: "m", н: "n", о: "o", п: "p", р: "r",
  с: "s", т: "t", у: "u", ф: "f", х: "h", ц: "c", ч: "ch", ш: "sh", щ: "sch",
  ъ: "", ы: "y", ь: "", э: "e", ю: "yu", я: "ya",
};

export function tagToSlug(tag: string): string {
  return tag
    .toLowerCase()
    .split("")
    .map((ch) => (CYR_TO_LAT[ch] !== undefined ? CYR_TO_LAT[ch] : ch))
    .join("")
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "");
}

export function getAllTagSlugs(): { slug: string; tag: string; count: number }[] {
  const map = new Map<string, { tag: string; count: number }>();
  for (const post of POSTS) {
    if (!post.tags) continue;
    for (const tag of post.tags) {
      const s = tagToSlug(tag);
      if (!s) continue;
      const cur = map.get(s);
      if (cur) cur.count += 1;
      else map.set(s, { tag, count: 1 });
    }
  }
  const out: { slug: string; tag: string; count: number }[] = [];
  map.forEach((v, slug) => out.push({ slug, tag: v.tag, count: v.count }));
  return out;
}

export function getPostsByTagSlug(tagSlug: string): BlogPost[] {
  return SORTED_POSTS.filter((p) => p.tags?.some((t) => tagToSlug(t) === tagSlug));
}

export function getTagBySlug(tagSlug: string): string | undefined {
  for (const p of POSTS) {
    if (!p.tags) continue;
    for (const t of p.tags) if (tagToSlug(t) === tagSlug) return t;
  }
  return undefined;
}
